// Spring Boot - Configure HTTP caching headers
// WebConfig.java

import org.springframework.context.annotation.Configuration;
import org.springframework.http.CacheControl;
import org.springframework.web.servlet.config.annotation.ResourceHandlerRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;
import java.util.concurrent.TimeUnit;

@Configuration
public class WebConfig implements WebMvcConfigurer {

    @Override
    public void addResourceHandlers(ResourceHandlerRegistry registry) {
        // Static resources with fingerprinting (hash in filename)
        // Cache for 1 year - safe because filename changes when content changes
        registry.addResourceHandler("/static/**")
            .addResourceLocations("classpath:/static/")
            .setCacheControl(CacheControl
                .maxAge(365, TimeUnit.DAYS)
                .cachePublic()
                .immutable());

        // Images and fonts - cache for 30 days
        registry.addResourceHandler("/images/**", "/fonts/**")
            .addResourceLocations("classpath:/static/images/", "classpath:/static/fonts/")
            .setCacheControl(CacheControl
                .maxAge(30, TimeUnit.DAYS)
                .cachePublic());

        // Webjars (third-party libraries) - cache for 1 year
        registry.addResourceHandler("/webjars/**")
            .addResourceLocations("classpath:/META-INF/resources/webjars/")
            .setCacheControl(CacheControl
                .maxAge(365, TimeUnit.DAYS)
                .cachePublic());
    }
}

// For controller responses
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.HttpHeaders;

@RestController
public class ApiController {

    // API endpoint with caching
    @GetMapping("/api/data")
    public ResponseEntity<Data> getData() {
        Data data = dataService.getData();

        // Cache for 5 minutes, private (not CDN-cacheable)
        return ResponseEntity.ok()
            .cacheControl(CacheControl
                .maxAge(5, TimeUnit.MINUTES)
                .cachePrivate())
            .eTag(String.valueOf(data.hashCode())) // ETag for validation
            .body(data);
    }

    // API with conditional request support
    @GetMapping("/api/users/{id}")
    public ResponseEntity<User> getUser(
            @PathVariable Long id,
            @RequestHeader(value = HttpHeaders.IF_NONE_MATCH, required = false) String ifNoneMatch) {

        User user = userService.getUser(id);
        String etag = String.valueOf(user.hashCode());

        // If ETag matches, return 304 Not Modified
        if (etag.equals(ifNoneMatch)) {
            return ResponseEntity
                .status(HttpStatus.NOT_MODIFIED)
                .eTag(etag)
                .build();
        }

        // Return full response with ETag
        return ResponseEntity.ok()
            .cacheControl(CacheControl
                .maxAge(10, TimeUnit.MINUTES)
                .cachePrivate())
            .eTag(etag)
            .body(user);
    }

    // HTML pages - short cache with revalidation
    @GetMapping("/")
    public ResponseEntity<String> getHomePage() {
        String html = templateEngine.process("home", context);

        return ResponseEntity.ok()
            .cacheControl(CacheControl
                .maxAge(1, TimeUnit.HOURS)
                .cachePublic()
                .mustRevalidate())
            .body(html);
    }

    // User-specific content - don't cache or use private cache
    @GetMapping("/dashboard")
    public ResponseEntity<Dashboard> getDashboard(@AuthenticationPrincipal User user) {
        Dashboard dashboard = dashboardService.getDashboard(user);

        return ResponseEntity.ok()
            .cacheControl(CacheControl
                .noCache() // Always revalidate
                .cachePrivate()) // Don't cache in CDN
            .eTag(String.valueOf(dashboard.hashCode()))
            .body(dashboard);
    }

    // Sensitive data - never cache
    @GetMapping("/api/payment-info")
    public ResponseEntity<PaymentInfo> getPaymentInfo() {
        PaymentInfo info = paymentService.getInfo();

        return ResponseEntity.ok()
            .cacheControl(CacheControl
                .noStore() // Never cache anywhere
                .noCache())
            .body(info);
    }
}

