// JUnit test for caching headers
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest
@AutoConfigureMockMvc
public class CachingTest {

    @Autowired
    private MockMvc mockMvc;

    @Test
    public void staticResourcesShouldHaveLongCacheHeaders() throws Exception {
        mockMvc.perform(get("/static/app.js"))
            .andExpect(status().isOk())
            .andExpect(header().exists("Cache-Control"))
            .andExpect(header().string("Cache-Control", 
                containsString("max-age=31536000"))) // 1 year
            .andExpect(header().string("Cache-Control", 
                containsString("public")));
    }

    @Test
    public void imagesShouldHaveMediumCacheHeaders() throws Exception {
        mockMvc.perform(get("/images/logo.png"))
            .andExpect(status().isOk())
            .andExpect(header().exists("Cache-Control"))
            .andExpect(header().string("Cache-Control", 
                containsString("max-age=2592000"))) // 30 days
            .andExpect(header().string("Cache-Control", 
                containsString("public")));
    }

    @Test
    public void apiShouldHavePrivateCacheWithETag() throws Exception {
        MvcResult result = mockMvc.perform(get("/api/data"))
            .andExpect(status().isOk())
            .andExpect(header().exists("Cache-Control"))
            .andExpect(header().string("Cache-Control", 
                containsString("private")))
            .andExpect(header().exists("ETag"))
            .andReturn();

        String etag = result.getResponse().getHeader("ETag");
        assertNotNull(etag);
    }

    @Test
    public void conditionalRequestShouldReturn304() throws Exception {
        // First request to get ETag
        MvcResult firstResult = mockMvc.perform(get("/api/users/1"))
            .andExpect(status().isOk())
            .andReturn();

        String etag = firstResult.getResponse().getHeader("ETag");

        // Second request with If-None-Match should return 304
        mockMvc.perform(get("/api/users/1")
                .header("If-None-Match", etag))
            .andExpect(status().isNotModified())
            .andExpect(header().string("ETag", etag));
    }

    @Test
    public void sensitiveDataShouldNotBeCached() throws Exception {
        mockMvc.perform(get("/api/payment-info"))
            .andExpect(status().isOk())
            .andExpect(header().exists("Cache-Control"))
            .andExpect(header().string("Cache-Control", 
                containsString("no-store")))
            .andExpect(header().string("Cache-Control", 
                containsString("no-cache")));
    }

    @Test
    public void htmlPagesShouldHaveShortCacheWithRevalidation() throws Exception {
        mockMvc.perform(get("/"))
            .andExpect(status().isOk())
            .andExpect(header().exists("Cache-Control"))
            .andExpect(header().string("Cache-Control", 
                anyOf(
                    containsString("max-age=3600"),    // 1 hour
                    containsString("must-revalidate")
                )));
    }
}

