// Express.js - Configure HTTP caching
const express = require('express');
const path = require('path');
const crypto = require('crypto');

const app = express();

// Static files with long cache (1 year)
// Assumes fingerprinted filenames (app.a1b2c3.js)
app.use('/static', express.static('public', {
  maxAge: '1y',           // Cache for 1 year
  immutable: true,        // Tell browsers file never changes
  setHeaders: (res, path) => {
    res.set('Cache-Control', 'public, max-age=31536000, immutable');
  }
}));

// Images and fonts - medium cache (30 days)
app.use('/images', express.static('public/images', {
  maxAge: '30d',
  setHeaders: (res, path) => {
    res.set('Cache-Control', 'public, max-age=2592000');
  }
}));

// API endpoints with caching
app.get('/api/data', (req, res) => {
  const data = getData();
  const etag = crypto.createHash('md5').update(JSON.stringify(data)).digest('hex');

  // Check If-None-Match header for conditional request
  if (req.headers['if-none-match'] === etag) {
    return res.status(304).end(); // Not Modified
  }

  res.set({
    'Cache-Control': 'private, max-age=300', // 5 minutes, private (no CDN)
    'ETag': etag,
    'Vary': 'Accept-Encoding'
  });

  res.json(data);
});

// HTML pages - short cache with revalidation
app.get('/', (req, res) => {
  res.set({
    'Cache-Control': 'public, max-age=3600, must-revalidate', // 1 hour
    'Vary': 'Accept-Encoding'
  });

  res.send('<html><body><h1>Home</h1></body></html>');
});

// User-specific content - private cache
app.get('/dashboard', authenticateUser, (req, res) => {
  const dashboard = getDashboard(req.user);
  const etag = crypto.createHash('md5').update(JSON.stringify(dashboard)).digest('hex');

  // Check conditional request
  if (req.headers['if-none-match'] === etag) {
    return res.status(304).end();
  }

  res.set({
    'Cache-Control': 'private, no-cache', // Always revalidate
    'ETag': etag
  });

  res.json(dashboard);
});

// Sensitive data - never cache
app.get('/api/payment-info', (req, res) => {
  const info = getPaymentInfo();

  res.set({
    'Cache-Control': 'no-store, no-cache, must-revalidate',
    'Pragma': 'no-cache',
    'Expires': '0'
  });

  res.json(info);
});

// Middleware to add default caching headers
app.use((req, res, next) => {
  // Default: don't cache unless explicitly set
  if (!res.get('Cache-Control')) {
    res.set('Cache-Control', 'no-cache');
  }
  next();
});

// Helper: Generate ETag from content
function generateETag(content) {
  return crypto
    .createHash('md5')
    .update(typeof content === 'string' ? content : JSON.stringify(content))
    .digest('hex');
}

// Advanced: Stale-while-revalidate
app.get('/api/slow-data', async (req, res) => {
  const data = await getSlowData();
  const etag = generateETag(data);

  res.set({
    // Serve stale content for 10 minutes while revalidating in background
    'Cache-Control': 'max-age=300, stale-while-revalidate=600',
    'ETag': etag
  });

  res.json(data);
});

app.listen(3000);

