// Mocha/Chai test for caching
const request = require('supertest');
const { expect } = require('chai');
const app = require('../app');

describe('HTTP Caching Tests', () => {

  it('should cache static files for 1 year', (done) => {
    request(app)
      .get('/static/app.js')
      .expect(200)
      .expect('Cache-Control', /max-age=31536000/)
      .expect('Cache-Control', /public/)
      .expect('Cache-Control', /immutable/)
      .end(done);
  });

  it('should include ETag for API responses', (done) => {
    request(app)
      .get('/api/data')
      .expect(200)
      .end((err, res) => {
        if (err) return done(err);

        expect(res.headers).to.have.property('etag');
        expect(res.headers['cache-control']).to.include('private');

        done();
      });
  });

  it('should return 304 Not Modified for conditional requests', (done) => {
    // First request to get ETag
    request(app)
      .get('/api/data')
      .expect(200)
      .end((err, res) => {
        if (err) return done(err);

        const etag = res.headers.etag;

        // Second request with If-None-Match
        request(app)
          .get('/api/data')
          .set('If-None-Match', etag)
          .expect(304)
          .end(done);
      });
  });

  it('should not cache sensitive data', (done) => {
    request(app)
      .get('/api/payment-info')
      .expect(200)
      .end((err, res) => {
        if (err) return done(err);

        expect(res.headers['cache-control']).to.include('no-store');
        expect(res.headers['cache-control']).to.include('no-cache');

        done();
      });
  });

  it('should cache images for 30 days', (done) => {
    request(app)
      .get('/images/logo.png')
      .expect(200)
      .expect('Cache-Control', /max-age=2592000/)
      .expect('Cache-Control', /public/)
      .end(done);
  });

  it('should set Vary header for compressed responses', (done) => {
    request(app)
      .get('/api/data')
      .expect('Vary', /Accept-Encoding/)
      .end(done);
  });
});

