# Nginx - Configure HTTP caching headers
# /etc/nginx/nginx.conf or /etc/nginx/sites-available/your-site

http {
    # Map to set expires based on file type
    map $sent_http_content_type $expires {
        default                    off;
        text/html                  1h;     # HTML - short cache
        text/css                   1y;     # CSS with fingerprint
        application/javascript     1y;     # JS with fingerprint
        application/json           5m;     # JSON APIs
        image/jpeg                 30d;    # Images
        image/png                  30d;
        image/gif                  30d;
        image/webp                 30d;
        image/svg+xml              30d;
        font/woff                  1y;     # Fonts
        font/woff2                 1y;
    }

    server {
        listen 443 ssl http2;
        server_name your-domain.com;

        # Enable expires map
        expires $expires;

        # Static files with fingerprints - long cache
        location ~* \.(?:css|js)$ {
            expires 1y;
            add_header Cache-Control "public, immutable";
            add_header Vary "Accept-Encoding";
        }

        # Images and fonts - medium cache
        location ~* \.(?:jpg|jpeg|gif|png|ico|svg|webp|woff|woff2|ttf|eot)$ {
            expires 30d;
            add_header Cache-Control "public";
        }

        # HTML files - short cache with revalidation
        location ~* \.html$ {
            expires 1h;
            add_header Cache-Control "public, must-revalidate";
        }

        # API endpoints - private cache with short TTL
        location /api/ {
            expires 5m;
            add_header Cache-Control "private";
            add_header Vary "Accept-Encoding";

            proxy_pass http://backend;
            proxy_set_header Host $host;
        }

        # User dashboard - no cache
        location /dashboard {
            add_header Cache-Control "private, no-cache, must-revalidate";
            proxy_pass http://backend;
        }

        # Sensitive endpoints - never cache
        location /api/payment {
            add_header Cache-Control "no-store, no-cache, must-revalidate";
            add_header Pragma "no-cache";
            add_header Expires "0";
            proxy_pass http://backend;
        }

        # Enable ETag generation
        etag on;

        # If-Modified-Since support
        if_modified_since before;
    }
}

