// Selenium test for caching
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.devtools.DevTools;
import org.openqa.selenium.devtools.v120.network.Network;
import org.testng.annotations.Test;
import org.testng.Assert;

@Test
public void verifyCacheHeadersPresent() {
    ChromeDriver driver = new ChromeDriver();
    DevTools devTools = driver.getDevTools();
    devTools.createSession();

    final String[] cacheControl = new String[1];
    final String[] etag = new String[1];

    devTools.send(Network.enable(Optional.empty(), Optional.empty(), Optional.empty()));

    devTools.addListener(Network.responseReceived(), response -> {
        Headers headers = response.getResponse().getHeaders();
        cacheControl[0] = headers.get("cache-control");
        etag[0] = headers.get("etag");
    });

    driver.get("https://your-domain.com");

    Assert.assertNotNull(cacheControl[0], "Cache-Control header missing");
    Assert.assertTrue(cacheControl[0].contains("max-age"), "max-age directive missing");

    driver.quit();
}
